I need you to build me a Droid script Quorum.js spk app to compile Android script. That will be the front end for my PC back end. That is outputting that back end to a very specific type of IP that isn't an http and isn't numbers it's weird ssh tunnel stuff 
Below is what gpt built but it won't work for the ssh tunnel address in the IP and may not have the right ai list since it's Claude, Gemini, co-pilot and grok that are actually going to be able to access this as gpt system won't allow me to connect any format or way through this

/*
  Quorum.js - DroidScript Frontend for Local AI Mediator
  - Prompts for tunnel IP on start
  - Runs background service to receive messages
  - UI: AI selector, transcript, input, send button
  - Sends user prompts to back end
  - Receives and displays AI outputs
*/

// Globals
var tunnelIP = "";
var svc;
var lay, txtTranscript, aiSelector, inpPrompt, btnSend;
var socket;

// Called when app starts
function OnStart() {
    // Prompt for tunnel IP
    tunnelIP = app.ShowTextDialog("Enter tunnel IP of the PC back end", "Tunnel IP");
    if (!tunnelIP) {
        app.Alert("Tunnel IP required");
        return;
    }

    // Create main layout
    lay = app.CreateLayout("linear", "VCenter,FillXY");

    // AI selector
    aiSelector = app.CreateSpinner(["Claude", "GPT", "Other"], 0.8);
    lay.AddChild(aiSelector);

    // Scrollable transcript
    txtTranscript = app.CreateText("", 0.9, 0.6, "multiline,Scroll");
    txtTranscript.SetTextSize(18);
    lay.AddChild(txtTranscript);

    // Prompt input
    inpPrompt = app.CreateTextEdit("", 0.9, 0.08, "singleline");
    lay.AddChild(inpPrompt);

    // Send button
    btnSend = app.CreateButton("Send", 0.5, 0.1);
    btnSend.SetOnTouch(SendPrompt);
    lay.AddChild(btnSend);

    app.AddLayout(lay);

    // Start background service
    svc = app.CreateService("QuorumService", "QuorumService", OnServiceReady);
    svc.SetOnMessage(OnServiceMessage);

    // Connect to back end
    ConnectToBackend();
}

// Service ready callback
function OnServiceReady() {
    console.log("Service ready");
}

// Handle messages from background service
function OnServiceMessage(msg) {
    AppendTranscript(msg);
}

// Append message to transcript
function AppendTranscript(msg) {
    var prev = txtTranscript.GetText();
    txtTranscript.SetText(prev + "\n" + msg);
    txtTranscript.ScrollTo(10000); // scroll to bottom
}

// Connect to back end via tunnel IP
function ConnectToBackend() {
    // Simple polling-based implementation
    setInterval(function() {
        try {
            var url = "http://" + tunnelIP + "/poll";
            var resp = app.HttpRequest(url, "GET");
            if (resp && resp.length > 0) {
                AppendTranscript(resp);
            }
        } catch (e) {
            console.log("Backend poll error: " + e);
        }
    }, 2000); // poll every 2s
}

// Send user prompt
function SendPrompt() {
    var prompt = inpPrompt.GetText();
    if (!prompt) return;
    var ai = aiSelector.GetText();
    var payload = JSON.stringify({ ai: ai, prompt: prompt });
    try {
        var url = "http://" + tunnelIP + "/send";
        app.HttpRequest(url, "POST", payload);
        AppendTranscript("User (" + ai + "): " + prompt);
        inpPrompt.SetText("");
    } catch (e) {
        console.log("Send error: " + e);
        app.Alert("Failed to send prompt");
    }
}

