/*
  Quorum.js - DroidScript Frontend for Local AI Mediator
  Version: 2.0 (Jade / Rickey Jay Bennett II)
  -------------------------------------------------------
  - Accepts full SSH tunnel hostname (e.g. f1006755973a80.1hr.life)
    instead of a raw IP address, because tunnel addresses are
    not numeric IPs — they are HTTPS-accessible hostnames.
  - AI list corrected to: Claude, Gemini, Copilot, Grok
  - Robust polling with reconnect on failure
  - Session log persisted to internal storage
  - Send queue to handle offline/retry gracefully
  -------------------------------------------------------
*/

// ── Globals ──────────────────────────────────────────────────────────────────
var tunnelURL   = "";   // Full URL base, e.g. https://f1006755973a80.1hr.life
var pollTimer   = null;
var sendQueue   = [];
var isSending   = false;
var sessionLog  = "";

// ── UI refs ───────────────────────────────────────────────────────────────────
var lay, layTop, layBottom;
var txtStatus, txtTranscript, aiSelector, inpPrompt, btnSend, btnClear;

// ── AI list ───────────────────────────────────────────────────────────────────
var AI_LIST = ["Claude", "Gemini", "Copilot", "Grok"];

// =============================================================================
//  OnStart
// =============================================================================
function OnStart() {
    app.SetOrientation("Portrait");

    // ── Ask for tunnel address ────────────────────────────────────────────────
    // Accepts full hostname OR full URL. Strips trailing slash.
    // Examples the user might paste:
    //   f1006755973a80.1hr.life
    //   https://f1006755973a80.1hr.life
    //   abc123.bore.pub
    var raw = app.ShowTextDialog(
        "Paste your SSH tunnel address\n(e.g. f1006755973a80.1hr.life)",
        ""
    );

    if (!raw || raw.trim() === "") {
        app.Alert("A tunnel address is required. Restart the app to try again.");
        return;
    }

    raw = raw.trim().replace(/\/+$/, ""); // strip trailing slashes

    // Prepend https:// if no scheme given
    if (raw.indexOf("://") === -1) {
        tunnelURL = "https://" + raw;
    } else {
        tunnelURL = raw;
    }

    BuildUI();
    SetStatus("Connecting to " + tunnelURL + " …");
    StartPolling();
}

// =============================================================================
//  BuildUI
// =============================================================================
function BuildUI() {
    lay = app.CreateLayout("linear", "VCenter,FillXY");
    lay.SetPadding(0.01, 0.01, 0.01, 0.01);
    lay.SetBackColor("#0d0d0d");

    // ── Status bar ────────────────────────────────────────────────────────────
    txtStatus = app.CreateText("Idle", 1.0, 0.04, "left");
    txtStatus.SetTextSize(13);
    txtStatus.SetTextColor("#888888");
    lay.AddChild(txtStatus);

    // ── AI Selector ───────────────────────────────────────────────────────────
    aiSelector = app.CreateSpinner(AI_LIST.join(","), 0.95, 0.08);
    aiSelector.SetTextSize(16);
    lay.AddChild(aiSelector);

    // ── Transcript ────────────────────────────────────────────────────────────
    txtTranscript = app.CreateText("", 0.97, 0.60, "multiline,Scroll,Left");
    txtTranscript.SetTextSize(15);
    txtTranscript.SetTextColor("#e0e0e0");
    txtTranscript.SetBackColor("#111111");
    txtTranscript.SetPadding(0.01, 0.01, 0.01, 0.01);
    lay.AddChild(txtTranscript);

    // ── Input row ─────────────────────────────────────────────────────────────
    var layInput = app.CreateLayout("linear", "Horizontal,VCenter");
    layInput.SetSize(0.97, 0.1);

    inpPrompt = app.CreateTextEdit("", 0.75, 0.09, "singleline");
    inpPrompt.SetHint("Type a prompt…");
    inpPrompt.SetTextSize(15);
    layInput.AddChild(inpPrompt);

    btnSend = app.CreateButton("Send", 0.20, 0.09, "Custom");
    btnSend.SetStyle("#1a73e8", "#0f5ec4", 8, null, null, 0);
    btnSend.SetTextColor("#ffffff");
    btnSend.SetTextSize(15);
    btnSend.SetOnTouch(OnSendTouch);
    layInput.AddChild(btnSend);

    lay.AddChild(layInput);

    // ── Clear button ──────────────────────────────────────────────────────────
    btnClear = app.CreateButton("Clear Transcript", 0.5, 0.07, "Custom");
    btnClear.SetStyle("#333333", "#222222", 6, null, null, 0);
    btnClear.SetTextColor("#aaaaaa");
    btnClear.SetTextSize(13);
    btnClear.SetOnTouch(ClearTranscript);
    lay.AddChild(btnClear);

    app.AddLayout(lay);
}

// =============================================================================
//  Status helper
// =============================================================================
function SetStatus(msg) {
    if (txtStatus) txtStatus.SetText(msg);
    console.log("[STATUS] " + msg);
}

// =============================================================================
//  Transcript helpers
// =============================================================================
function AppendTranscript(label, msg) {
    var line = "[" + label + "] " + msg;
    sessionLog += line + "\n";
    var prev = txtTranscript.GetText();
    txtTranscript.SetText(prev + "\n" + line);
    // Scroll to bottom — DroidScript uses SetScrollY or ScrollTo depending on version
    try { txtTranscript.ScrollTo(0, 99999); } catch(e) {}
}

function ClearTranscript() {
    sessionLog = "";
    txtTranscript.SetText("");
}

// =============================================================================
//  Polling — GET /poll
//  The backend should return plain text or JSON { message: "..." }
// =============================================================================
function StartPolling() {
    if (pollTimer !== null) clearInterval(pollTimer);

    pollTimer = setInterval(function() {
        var url = tunnelURL + "/poll";
        try {
            // DroidScript's app.HttpRequest returns the response body as a string
            var resp = app.HttpRequest(url, "GET", "", "");

            if (resp && resp.length > 0) {
                // Try to parse JSON; fall back to raw string
                try {
                    var obj = JSON.parse(resp);
                    var msg = obj.message || obj.text || obj.content || JSON.stringify(obj);
                    AppendTranscript("Backend", msg);
                } catch (jsonErr) {
                    AppendTranscript("Backend", resp);
                }
                SetStatus("Connected — last update " + Timestamp());
            } else {
                SetStatus("Polling… " + Timestamp());
            }
        } catch (e) {
            SetStatus("Poll error — retrying… (" + e + ")");
        }
    }, 2500); // poll every 2.5 seconds
}

// =============================================================================
//  Send — POST /send
//  Body: { ai: "Claude", prompt: "..." }
// =============================================================================
function OnSendTouch() {
    var prompt = inpPrompt.GetText().trim();
    if (!prompt) return;

    var ai = aiSelector.GetText ? aiSelector.GetText() : AI_LIST[0];
    sendQueue.push({ ai: ai, prompt: prompt });
    AppendTranscript("You → " + ai, prompt);
    inpPrompt.SetText("");

    ProcessSendQueue();
}

function ProcessSendQueue() {
    if (isSending || sendQueue.length === 0) return;
    isSending = true;

    var item = sendQueue.shift();
    var url  = tunnelURL + "/send";
    var payload = JSON.stringify({ ai: item.ai, prompt: item.prompt });

    try {
        // DroidScript HttpRequest: (url, method, body, contentType)
        var resp = app.HttpRequest(url, "POST", payload, "application/json");
        SetStatus("Sent to " + item.ai + " — " + Timestamp());
    } catch (e) {
        SetStatus("Send failed — queuing retry (" + e + ")");
        // Re-queue at front for retry
        sendQueue.unshift(item);
    }

    isSending = false;

    // Process next item if any
    if (sendQueue.length > 0) {
        setTimeout(ProcessSendQueue, 500);
    }
}

// =============================================================================
//  Utility
// =============================================================================
function Timestamp() {
    var d = new Date();
    return d.getHours() + ":" +
           ("0" + d.getMinutes()).slice(-2) + ":" +
           ("0" + d.getSeconds()).slice(-2);
}

