/*
  Quorum.js - DroidScript Frontend for Local AI Mediator
  Version: 3.0 (Jade / Rickey Jay Bennett II)
  -------------------------------------------------------
  ARCHITECTURE NOTE:
  This app does NOT call any AI API directly.
  It talks exclusively to the PC back end over the SSH tunnel.
  The PC back end is responsible for all browser automation —
  clicking the upload button, choosing the file, submitting
  the prompt — on whichever AI web interface is selected.

  The app sends structured JSON commands to the back end:
    { command: "upload",  ai: "Claude", path: "/sdcard/file.pdf" }
    { command: "prompt",  ai: "Gemini", text: "Summarize this" }
    { command: "poll" }   ← the back end returns any pending AI output

  AI web interfaces targeted by back-end automation:
    Claude   → claude.ai
    Gemini   → gemini.google.com
    Copilot  → copilot.microsoft.com
    Grok     → grok.com (x.ai)

  The back end is expected to expose:
    POST /command   { command, ai, [path], [text] }
    GET  /poll      → { message: "..." } or ""
  -------------------------------------------------------
*/

// ── Globals ───────────────────────────────────────────────────────────────────
var tunnelURL  = "";
var pollTimer  = null;
var sendQueue  = [];
var isSending  = false;

// ── AI list and their known web URLs (informational, for the back end) ────────
var AI_LIST = ["Claude", "Gemini", "Copilot", "Grok"];
var AI_URLS = {
    "Claude":  "claude.ai",
    "Gemini":  "gemini.google.com",
    "Copilot": "copilot.microsoft.com",
    "Grok":    "grok.com"
};

// ── UI refs ───────────────────────────────────────────────────────────────────
var lay;
var txtStatus, txtTranscript;
var aiSelector;
var inpPrompt, btnSend;
var btnUpload, btnClear;
var lblAIURL;

// =============================================================================
//  OnStart
// =============================================================================
function OnStart() {
    app.SetOrientation("Portrait");

    var raw = app.ShowTextDialog(
        "Paste your SSH tunnel address\n(e.g. f1006755973a80.1hr.life)",
        ""
    );

    if (!raw || raw.trim() === "") {
        app.Alert("A tunnel address is required. Restart to try again.");
        return;
    }

    raw = raw.trim().replace(/\/+$/, "");
    tunnelURL = (raw.indexOf("://") === -1) ? "https://" + raw : raw;

    BuildUI();
    SetStatus("Connecting to " + tunnelURL + " …");
    StartPolling();
}

// =============================================================================
//  BuildUI
// =============================================================================
function BuildUI() {
    lay = app.CreateLayout("linear", "VCenter,FillXY");
    lay.SetPadding(0.01, 0.01, 0.01, 0.01);
    lay.SetBackColor("#0d0d0d");

    // ── Status bar ────────────────────────────────────────────────────────────
    txtStatus = app.CreateText("Idle", 1.0, 0.04, "left");
    txtStatus.SetTextSize(13);
    txtStatus.SetTextColor("#888888");
    lay.AddChild(txtStatus);

    // ── AI selector row ───────────────────────────────────────────────────────
    var layAI = app.CreateLayout("linear", "Horizontal,VCenter");
    layAI.SetSize(0.97, 0.09);

    aiSelector = app.CreateSpinner(AI_LIST.join(","), 0.55, 0.08);
