        // (e.g. via a shared folder, a prior transfer, or an adb push).
        // The command tells the back end WHICH file to upload and WHERE (which AI site).

        AppendTranscript("You",
            "📎 Upload request: " + path.split("/").pop() +
            " → " + ai + " (" + AI_URLS[ai] + ")"
        );

        EnqueueCommand({
            command:   "upload",
            ai:        ai,
            site:      AI_URLS[ai],
            path:      path,
            filename:  path.split("/").pop()
        });
    });
}

// =============================================================================
//  Prompt send
// =============================================================================
function OnSendTouch() {
    var text = inpPrompt.GetText().trim();
    if (!text) return;

    var ai = aiSelector.GetText ? aiSelector.GetText() : AI_LIST[0];

    AppendTranscript("You → " + ai, text);
    inpPrompt.SetText("");

    EnqueueCommand({
        command: "prompt",
        ai:      ai,
        site:    AI_URLS[ai],
        text:    text
    });
}

// =============================================================================
//  Command queue — serialises all outgoing commands
// =============================================================================
function EnqueueCommand(cmdObj) {
    sendQueue.push(cmdObj);
    ProcessQueue();
}

function ProcessQueue() {
    if (isSending || sendQueue.length === 0) return;
    isSending = true;

    var cmd     = sendQueue.shift();
    var payload = JSON.stringify(cmd);

    try {
        app.HttpRequest(tunnelURL + "/command", "POST", payload, "application/json");
        SetStatus("[" + cmd.command + "] sent — " + Timestamp());
    } catch (e) {
        SetStatus("Send failed — retrying… (" + e + ")");
        sendQueue.unshift(cmd);
    }

    isSending = false;

    if (sendQueue.length > 0) {
        setTimeout(ProcessQueue, 600);
    }
}

// =============================================================================
//  Polling — back end returns scraped AI output and upload confirmations
// =============================================================================
function StartPolling() {
    if (pollTimer !== null) clearInterval(pollTimer);

    pollTimer = setInterval(function() {
        try {
            var resp = app.HttpRequest(tunnelURL + "/poll", "GET", "", "");

            if (resp && resp.length > 0) {
                try {
                    var obj  = JSON.parse(resp);
                    var type = obj.type    || "response";
                    var ai   = obj.ai      || "Backend";
                    var msg  = obj.message || obj.text || obj.content || JSON.stringify(obj);

                    // Label the transcript line by response type
                    var label;
                    if      (type === "upload_ok")   label = "✅ Upload OK ← "    + ai;
                    else if (type === "upload_fail") label = "❌ Upload FAIL ← "  + ai;
                    else if (type === "upload_progress") label = "⏳ Uploading ← " + ai;
                    else if (type === "error")       label = "⚠️  Error ← "        + ai;
                    else                             label = "← " + ai;

                    AppendTranscript(label, msg);
                } catch (jsonErr) {
                    AppendTranscript("← Backend", resp);
                }
                SetStatus("Live — " + Timestamp());
            } else {
                SetStatus("Polling… " + Timestamp());
            }
        } catch (e) {
            SetStatus("Poll error — " + e);
        }
    }, 2500);
}

// =============================================================================
//  Transcript / utility
// =============================================================================
function AppendTranscript(label, msg) {
    var prev = txtTranscript.GetText();
    txtTranscript.SetText(prev + "\n[" + label + "]  " + msg);
    try { txtTranscript.ScrollTo(0, 99999); } catch(e) {}
}

function ClearTranscript() {
    txtTranscript.SetText("");
}

function SetStatus(msg) {
    if (txtStatus) txtStatus.SetText(msg);
}

function Timestamp() {
    var d = new Date();
    return d.getHours() + ":" +
           ("0" + d.getMinutes()).slice(-2) + ":" +
           ("0" + d.getSeconds()).slice(-2);
}

