## Current DroidScript source (Quarum.js.txt) — REWRITE THIS

```javascript
/*
  Quorum.js - DroidScript Frontend for Local AI Mediator
  - Prompts for tunnel IP on start
  - Runs background service to receive messages
  - UI: AI selector, transcript, input, send button
  - Sends user prompts to back end
  - Receives and displays AI outputs
*/

// Globals
var tunnelIP = "";
var svc;
var lay, txtTranscript, aiSelector, inpPrompt, btnSend;
var socket;

// Called when app starts
function OnStart() {
    // Prompt for tunnel IP
    tunnelIP = app.ShowTextDialog("Enter tunnel IP of the PC back end", "Tunnel IP");
    if (!tunnelIP) {
        app.Alert("Tunnel IP required");
        return;
    }

    // Create main layout
    lay = app.CreateLayout("linear", "VCenter,FillXY");

    // AI selector
    aiSelector = app.CreateSpinner(["Claude", "GPT", "Other"], 0.8);
    lay.AddChild(aiSelector);

    // Scrollable transcript
    txtTranscript = app.CreateText("", 0.9, 0.6, "multiline,Scroll");
    txtTranscript.SetTextSize(18);
    lay.AddChild(txtTranscript);

    // Prompt input
    inpPrompt = app.CreateTextEdit("", 0.9, 0.08, "singleline");
    lay.AddChild(inpPrompt);

    // Send button
    btnSend = app.CreateButton("Send", 0.5, 0.1);
    btnSend.SetOnTouch(SendPrompt);
    lay.AddChild(btnSend);

    app.AddLayout(lay);

    // Start background service
    svc = app.CreateService("QuorumService", "QuorumService", OnServiceReady);
    svc.SetOnMessage(OnServiceMessage);

    // Connect to back end
    ConnectToBackend();
}

function OnServiceReady() { console.log("Service ready"); }

function OnServiceMessage(msg) { AppendTranscript(msg); }

function AppendTranscript(msg) {
    var prev = txtTranscript.GetText();
    txtTranscript.SetText(prev + "\n" + msg);
    txtTranscript.ScrollTo(10000);
}

function ConnectToBackend() {
    setInterval(function() {
        try {
            var url = "http://" + tunnelIP + "/poll";
            var resp = app.HttpRequest(url, "GET");
            if (resp && resp.length > 0) {
                AppendTranscript(resp);
            }
        } catch (e) {
            console.log("Backend poll error: " + e);
        }
    }, 2000);
}

function SendPrompt() {
    var prompt = inpPrompt.GetText();
    if (!prompt) return;
    var ai = aiSelector.GetText();
    var payload = JSON.stringify({ ai: ai, prompt: prompt });
    try {
        var url = "http://" + tunnelIP + "/send";
        app.HttpRequest(url, "POST", payload);
        AppendTranscript("User (" + ai + "): " + prompt);
        inpPrompt.SetText("");
    } catch (e) {
        console.log("Send error: " + e);
        app.Alert("Failed to send prompt");
    }
}
```

---

## What the new UI must do

### Layout requirements
- Keep the tunnel IP prompt on start (unchanged)
- Keep the scrollable transcript display (unchanged)
- Keep the text input + Send button for prompts
- **Replace** the single "Claude/GPT/Other" spinner with a proper AI targeting system
- **Add** action/sidebar/upload button panels

### New UI elements needed

**1. AI target selector (multi-select or toggle buttons)**
Replace the spinner with toggle buttons so the user can select one or multiple
AIs to receive the next prompt:
- [ Claude ] [ Gemini ] [ Grok ] [ Copilot ]
- All selected by default. Tap to toggle. Selected = highlighted.
- When Send is pressed, `targets` array in POST /send contains only selected AIs.
- If all selected → omit targets field (sends to all, backend handles it).

**2. Sidebar / Navigation buttons — one row per AI**
Small buttons grouped by AI. Each row has the AI name label + its buttons:

Claude:   [Sidebar] [New Chat] [Projects] [Upload]
Gemini:   [New Chat] [Upload]
Grok:     [Sidebar] [History] [Private] [Upload]
Copilot:  [Sidebar] [New Chat] [Library] [Upload]

Tapping any button → POST /action {"ai":"...", "action":"..."}

**3. Feature mode buttons (collapsible or second row)**
Claude:   [Write] [Learn] [Code] [Life]
Gemini:   [Image] [Music] [Learn] [Video]
Grok:     [DeepSearch] [Imagine] [Personas]
Copilot:  [Smart] [Sources]

**4. Conversation switcher**
- Button "Convos" per AI → calls GET /conversations?ai=...
- Shows a list dialog with the returned conversation titles
- User picks one → POST /switch {"ai":"...", "title":"..."}

**5. IRC command shortcuts**
Buttons or a command row for common commands:
[Kill] [Mute Claude] [Mute Gemini] [Mute Grok] [Mute Copilot] [Resume] [Status]
These post to POST /command {"command":"#/kill"} etc.

---

## DroidScript API reference (key methods)

```javascript
// HTTP
app.HttpRequest(url, method, body, headers)  // returns response string
// For POST with JSON body:
app.HttpRequest("http://"+tunnelIP+"/send", "POST",
    JSON.stringify({prompt:"hi", targets:["claude"]}),
    "Content-Type:application/json")

// UI
app.CreateLayout("linear", "VCenter,FillXY")
app.CreateLayout("linear", "Horizontal")     // horizontal row
lay.AddChild(widget)
lay.SetPadding(left, top, right, bottom)

app.CreateButton("Label", width, height)     // width/height 0..1 = fraction of screen
btn.SetOnTouch(functionRef)
btn.SetBackColor("#hex")
btn.SetTextColor("#hex")

app.CreateText("", width, height, "multiline,Scroll")
txt.SetText(str)
txt.GetText()
txt.ScrollTo(99999)                          // scroll to bottom

app.CreateTextEdit("", width, height, "singleline")
edit.GetText()
edit.SetText(str)

app.CreateSpinner(["A","B","C"], width)
spinner.GetText()                            // returns selected item

app.ShowTextDialog("message", "title")       // blocking, returns string
app.ShowListDialog("title", ["a","b","c"], callback)   // async list picker
// callback receives selected item string

app.Alert("message")
console.log("debug")

// Layout nesting
var row = app.CreateLayout("linear","Horizontal")
row.AddChild(btn1)
