// ═══════════════════════════════════════════════════════════════════════════
//  UI helpers
// ═══════════════════════════════════════════════════════════════════════════

// Persistent refs needed across callbacks
var _statusRef, _transcriptRef, _promptRef;

function SectionLabel(text) {
    var lbl = app.CreateText(text, 0.97, 0.05, "left");
    lbl.SetTextSize(11);
    lbl.SetTextColor("#446644");
    lbl.SetPadding(0, 0.005, 0, 0);
    return lbl;
}

function MkBtn(label, w, h) {
    var b = app.CreateButton(label, w, h);
    b.SetTextSize(12);
    b.SetBackColor("#1e1e1e");
    b.SetTextColor("#cccccc");
    return b;
}

// A horizontal row of action buttons for one AI
function ActionRow(ai, actions) {
    var row = app.CreateLayout("linear", "Horizontal");
    row.SetSize(0.97, 0.09);
    actions.forEach(function(pair) {
        var label  = pair[0];
        var action = pair[1];
        var b = MkBtn(label, 0.23, 0.08);
        if (action === "upload") {
            b.SetBackColor("#1b361b");
            b.SetTextColor("#66cc66");
        }
        b.SetOnTouch(function() { PostAction(ai, action); });
        row.AddChild(b);
    });
    return row;
}

// A single "Convos" button that fetches and shows a list dialog
function ConvoRow(ai) {
    var row = app.CreateLayout("linear", "Horizontal");
    row.SetSize(0.97, 0.08);

    var b = MkBtn("Convos ▾  " + AI_LABELS[ai], 0.50, 0.07);
    b.SetBackColor("#1a1a2e");
    b.SetTextColor("#8888ff");
    b.SetOnTouch(function() { FetchConvos(ai); });
    row.AddChild(b);
    return row;
}

function SetTargetBtnColor(btn, active) {
    if (active) {
        btn.SetBackColor("#1a3a1a");
        btn.SetTextColor("#88ff88");
    } else {
        btn.SetBackColor("#2a2a2a");
        btn.SetTextColor("#555555");
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  Target toggle
// ═══════════════════════════════════════════════════════════════════════════
function ToggleTarget(ai, btn) {
    aiTargets[ai] = !aiTargets[ai];
    SetTargetBtnColor(btn, aiTargets[ai]);
}

function GetTargetArray() {
    var t = [];
    AI_KEYS.forEach(function(ai) { if (aiTargets[ai]) t.push(ai); });
    return t;
}

// ═══════════════════════════════════════════════════════════════════════════
//  Send prompt
// ═══════════════════════════════════════════════════════════════════════════
function OnSend() {
    var text = _promptRef.GetText().trim();
    if (!text) return;

    // IRC command typed directly
    if (text.indexOf("#/") === 0) {
        SendCommand(text);
        _promptRef.SetText("");
        return;
    }

    var targets = GetTargetArray();
    var payload = { prompt: text, ai: "user" };
    // Only include targets field if fewer than all four are selected
    if (targets.length < AI_KEYS.length) {
        payload.targets = targets;
    }

    AppendTranscript("You → [" + (targets.join(", ") || "none") + "]", text);
    _promptRef.SetText("");

    try {
        app.HttpRequest(
            "http://" + tunnelIP + "/send",
            "POST",
            JSON.stringify(payload),
            "Content-Type:application/json"
        );
        SetStatus("Prompt sent — " + Stamp());
    } catch(e) {
        SetStatus("Send error: " + e);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  IRC command sender
// ═══════════════════════════════════════════════════════════════════════════
function SendCommand(cmd) {
    AppendTranscript("CMD", cmd);
    try {
        app.HttpRequest(
            "http://" + tunnelIP + "/command",
            "POST",
            JSON.stringify({ command: cmd }),
            "Content-Type:application/json"
        );
        SetStatus("Command sent: " + cmd + " — " + Stamp());
    } catch(e) {
        SetStatus("Command error: " + e);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  Action button handler  → POST /action
// ═══════════════════════════════════════════════════════════════════════════
function PostAction(ai, action) {
    try {
        app.HttpRequest(
            "http://" + tunnelIP + "/action",
            "POST",
            JSON.stringify({ ai: ai, action: action }),
            "Content-Type:application/json"
        );
        SetStatus("[" + ai + "] action: " + action + " — " + Stamp());
        AppendTranscript("Action → " + AI_LABELS[ai], action);
    } catch(e) {
        SetStatus("Action error: " + e);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  Conversation switcher  → GET /conversations  then POST /switch
// ═══════════════════════════════════════════════════════════════════════════
function FetchConvos(ai) {
    SetStatus("Fetching conversations for " + AI_LABELS[ai] + "…");
    try {
        var resp = app.HttpRequest(
            "http://" + tunnelIP + "/conversations?ai=" + ai,
            "GET", "", ""
        );
        if (!resp || resp.length === 0) {
            app.Alert("No conversations returned for " + AI_LABELS[ai]);
            return;
        }
        var data  = JSON.parse(resp);
        var convos = data.conversations || [];
        if (convos.length === 0) {
            app.Alert("No conversations found for " + AI_LABELS[ai]);
            return;
        }
        var titles = [];
        convos.forEach(function(c) { titles.push(c.title); });

        app.ShowListDialog(
            "Switch conversation — " + AI_LABELS[ai],
            titles,
            function(selected) {
                if (!selected) return;
                try {
                    app.HttpRequest(
                        "http://" + tunnelIP + "/switch",
                        "POST",
                        JSON.stringify({ ai: ai, title: selected }),
                        "Content-Type:application/json"
                    );
                    AppendTranscript("Switch → " + AI_LABELS[ai], selected);
                    SetStatus("Switched " + AI_LABELS[ai] + " to: " + selected);
                } catch(e) {
                    SetStatus("Switch error: " + e);
                }
            }
        );
    } catch(e) {
        SetStatus("Convos fetch error: " + e);
    }
}

// ═══════════════════════════════════════════════════════════════════════════
//  Polling  → GET /poll every 2000 ms
// ═══════════════════════════════════════════════════════════════════════════
function StartPolling() {
    if (pollTimer) clearInterval(pollTimer);
    pollTimer = setInterval(function() {
        try {
            var resp = app.HttpRequest(
                "http://" + tunnelIP + "/poll",
                "GET", "", ""
            );
            if (resp && resp.length > 0) {
                AppendTranscript("←", resp);
                SetStatus("Response received — " + Stamp());
            }
        } catch(e) {
            SetStatus("Poll error — " + Stamp());
        }
    }, 2000);
}

// ═══════════════════════════════════════════════════════════════════════════
//  Transcript / status helpers
// ═══════════════════════════════════════════════════════════════════════════
function AppendTranscript(label, msg) {
    if (!_transcriptRef) return;
    var prev = _transcriptRef.GetText();
    _transcriptRef.SetText(prev + "\n[" + label + "]  " + msg);
    try { _transcriptRef.ScrollTo(99999); } catch(e) {}
}

function SetStatus(msg) {
    if (_statusRef) _statusRef.SetText(msg);
}

function Stamp() {
    var d = new Date();
    return d.getHours() + ":" +
           ("0" + d.getMinutes()).slice(-2) + ":" +
           ("0" + d.getSeconds()).slice(-2);
}

