// ═══════════════════════════════════════════════════════════════════════════
//  Conversation switcher  → GET /conversations  then POST /switch
//  DroidScript ShowListDialog requires a named global function, not an
//  inline callback — so we stash the active AI in _convoAI and use
//  OnConvoSelected as the named handler.
// ═══════════════════════════════════════════════════════════════════════════
var _convoAI = "";

function FetchConvos(ai) {
    _convoAI = ai;
    SetStatus("Fetching conversations for " + AI_LABELS[ai] + "…");
    try {
        var resp = app.HttpRequest(
            "http://" + tunnelIP + "/conversations?ai=" + ai,
            "GET", "", ""
        );
        if (!resp || resp.length === 0) {
            app.Alert("No conversations returned for " + AI_LABELS[ai]);
            return;
        }
        var data   = JSON.parse(resp);
        var convos = data.conversations || [];
        if (convos.length === 0) {
            app.Alert("No conversations found for " + AI_LABELS[ai]);
            return;
        }
        var titles = [];
        for (var i = 0; i < convos.length; i++) {
            titles.push(convos[i].title);
        }
        // Pass the handler as a named global function reference
        app.ShowListDialog("Switch — " + AI_LABELS[ai], titles, OnConvoSelected);
    } catch(e) {
        SetStatus("Convos fetch error: " + e);
    }
}

// Named global callback for ShowListDialog
function OnConvoSelected(selected) {
    if (!selected) return;
    var ai = _convoAI;
    try {
        app.HttpRequest(
            "http://" + tunnelIP + "/switch",
            "POST",
            JSON.stringify({ ai: ai, title: selected }),
            "Content-Type:application/json"
        );
        AppendTranscript("Switch → " + AI_LABELS[ai], selected);
        SetStatus("Switched " + AI_LABELS[ai] + " to: " + selected);
    } catch(e) {
        SetStatus("Switch error: " + e);
    }
}

