/*
  Quarum.js — DroidScript Mobile Terminal
  Version: 4.1 (Jade / Rickey Jay Bennett II)
  ─────────────────────────────────────────────────────────────────────────────
  Fixes vs 4.0:
  - ShowListDialog now uses a named global function (OnConvoSelected) instead
    of an inline callback — DroidScript's dlg.js requires this.
  - All forEach loops replaced with standard for loops — older SpiderMonkey
    engine in DroidScript chokes on closure captures inside forEach.
  - SetOnTouch handlers use named wrapper functions to avoid closure issues.

  Backend endpoints:
    POST /send          { prompt, targets[], ai }
    GET  /poll          → response string
    POST /action        { ai, action }
    GET  /conversations?ai=...  → { ai, conversations:[{title,href}] }
    POST /switch        { ai, title }
    POST /upload        { ai, filePath }
    POST /command       { command }

  AIs: claude · gemini · grok · copilot   (ChatGPT removed permanently)
  ─────────────────────────────────────────────────────────────────────────────
*/

// ═══════════════════════════════════════════════════════════════════════════
//  Globals
// ═══════════════════════════════════════════════════════════════════════════
var tunnelIP  = "";
var pollTimer = null;

var aiTargets = { claude: true, gemini: true, grok: true, copilot: true };
var AI_KEYS   = ["claude", "gemini", "grok", "copilot"];
var AI_LABELS = { claude:"Claude", gemini:"Gemini", grok:"Grok", copilot:"Copilot" };

// Refs populated in BuildUI
var _statusRef     = null;
var _transcriptRef = null;
var _promptRef     = null;
var _targetBtns    = { claude:null, gemini:null, grok:null, copilot:null };

// Stash for convo switcher callback
var _convoAI = "";

// ═══════════════════════════════════════════════════════════════════════════
//  OnStart
// ═══════════════════════════════════════════════════════════════════════════
function OnStart() {
    app.SetOrientation("Portrait");

    tunnelIP = app.ShowTextDialog(
        "Enter tunnel address of the PC back end\n(e.g. f1006755973a80.lhr.live)",
        "Tunnel address"
    );
    if (!tunnelIP) {
        app.Alert("Tunnel address required. Restart to try again.");
        return;
    }
    tunnelIP = tunnelIP.trim().replace(/\/+$/, "");

    BuildUI();
    StartPolling();
}

// ═══════════════════════════════════════════════════════════════════════════
//  BuildUI — no forEach, no inline SetOnTouch lambdas
// ═══════════════════════════════════════════════════════════════════════════
function BuildUI() {

    var root = app.CreateScroller(1.0, 1.0, "vertical");
    root.SetBackColor("#0d0d0d");

    var main = app.CreateLayout("linear", "VCenter,FillXY");
    main.SetPadding(0.01, 0.01, 0.01, 0.01);
    main.SetBackColor("#0d0d0d");

    // ── Status bar ───────────────────────────────────────────────────────
    var st = app.CreateText("Connecting…", 1.0, 0.04, "left");
    st.SetTextSize(12);
    st.SetTextColor("#666666");
    main.AddChild(st);
    _statusRef = st;

    // ── AI Target Toggles ────────────────────────────────────────────────
    main.AddChild(SectionLabel("TARGET AIs  (tap to toggle)"));

    var rowT = app.CreateLayout("linear", "Horizontal");
    rowT.SetSize(0.97, 0.09);

    var btnClaude  = MkBtn("Claude",  0.23, 0.08);
    var btnGemini  = MkBtn("Gemini",  0.23, 0.08);
    var btnGrok    = MkBtn("Grok",    0.23, 0.08);
    var btnCopilot = MkBtn("Copilot", 0.23, 0.08);

    SetTargetBtnColor(btnClaude,  true);
    SetTargetBtnColor(btnGemini,  true);
    SetTargetBtnColor(btnGrok,    true);
    SetTargetBtnColor(btnCopilot, true);

    btnClaude.SetOnTouch(ToggleClaude);
    btnGemini.SetOnTouch(ToggleGemini);
    btnGrok.SetOnTouch(ToggleGrok);
    btnCopilot.SetOnTouch(ToggleCopilot);

    _targetBtns.claude  = btnClaude;
    _targetBtns.gemini  = btnGemini;
    _targetBtns.grok    = btnGrok;
    _targetBtns.copilot = btnCopilot;

    rowT.AddChild(btnClaude);
    rowT.AddChild(btnGemini);
    rowT.AddChild(btnGrok);
    rowT.AddChild(btnCopilot);
    main.AddChild(rowT);

    // ── Transcript ───────────────────────────────────────────────────────
    main.AddChild(SectionLabel("TRANSCRIPT"));

    var tx = app.CreateText("", 0.97, 0.30, "multiline,Scroll,Left");
    tx.SetTextSize(13);
    tx.SetTextColor("#dddddd");
    tx.SetBackColor("#111111");
    tx.SetPadding(0.01, 0.01, 0.01, 0.01);
    main.AddChild(tx);
    _transcriptRef = tx;

    // ── Prompt row ───────────────────────────────────────────────────────
    var rowIn = app.CreateLayout("linear", "Horizontal,VCenter");
    rowIn.SetSize(0.97, 0.10);

    var inp = app.CreateTextEdit("", 0.73, 0.09, "singleline");
    inp.SetH

