// ═══════════════════════════════════════════════════════════════════════
//  UI helpers
// ═══════════════════════════════════════════════════════════════════════
function SectionLabel(text) {
    var lbl = app.CreateText(text, 0.97, 0.05, "left");
    lbl.SetTextSize(11);
    lbl.SetTextColor("#446644");
    lbl.SetPadding(0, 0.005, 0, 0);
    return lbl;
}

function MkBtn(label, w, h) {
    var b = app.CreateButton(label, w, h);
    b.SetTextSize(12);
    b.SetBackColor("#1e1e1e");
    b.SetTextColor("#cccccc");
    return b;
}

function SetTargetBtnColor(btn, active) {
    if (active) { btn.SetBackColor("#1a3a1a"); btn.SetTextColor("#88ff88"); }
    else        { btn.SetBackColor("#2a2a2a"); btn.SetTextColor("#555555"); }
}

// ═══════════════════════════════════════════════════════════════════════
//  Target toggle named handlers
// ═══════════════════════════════════════════════════════════════════════
function ToggleClaude()  { aiTargets.claude  = !aiTargets.claude;  SetTargetBtnColor(_btnClaude,  aiTargets.claude);  }
function ToggleGemini()  { aiTargets.gemini  = !aiTargets.gemini;  SetTargetBtnColor(_btnGemini,  aiTargets.gemini);  }
function ToggleGrok()    { aiTargets.grok    = !aiTargets.grok;    SetTargetBtnColor(_btnGrok,    aiTargets.grok);    }
function ToggleCopilot() { aiTargets.copilot = !aiTargets.copilot; SetTargetBtnColor(_btnCopilot, aiTargets.copilot); }

// ═══════════════════════════════════════════════════════════════════════
//  Send prompt
// ═══════════════════════════════════════════════════════════════════════
function GetTargetArray() {
    var t = [];
    for (var i = 0; i < AI_KEYS.length; i++) {
        if (aiTargets[AI_KEYS[i]]) t.push(AI_KEYS[i]);
    }
    return t;
}

function OnSend() {
    var text = _promptRef.GetText().trim();
    if (!text) return;

    if (text.indexOf("#/") === 0) {
        SendCommand(text);
        _promptRef.SetText("");
        return;
    }

    var targets = GetTargetArray();
    var payload = { prompt: text, ai: "user" };
    if (targets.length < AI_KEYS.length) payload.targets = targets;

    AppendTranscript("You → [" + targets.join(", ") + "]", text);
    _promptRef.SetText("");

    try {
        app.HttpRequest("http://" + tunnelIP + "/send", "POST",
            JSON.stringify(payload), "Content-Type:application/json");
        SetStatus("Prompt sent — " + Stamp());
    } catch(e) { SetStatus("Send error: " + e); }
}

// ═══════════════════════════════════════════════════════════════════════
//  IRC command sender
// ═══════════════════════════════════════════════════════════════════════
function SendCommand(cmd) {
    AppendTranscript("CMD", cmd);
    try {
        app.HttpRequest("http://" + tunnelIP + "/command", "POST",
            JSON.stringify({ command: cmd }), "Content-Type:application/json");
        SetStatus("Command: " + cmd + " — " + Stamp());
    } catch(e) { SetStatus("Command error: " + e); }
}

function CmdKill()   { SendCommand("#/kill");   }
function CmdResume() { SendCommand("#/resume"); }
function CmdStatus() { SendCommand("#/status"); }
function CmdClear()  { SendCommand("#/clear");  }

function MuteClaude()    { SendCommand("#/mute claude");     }
function MuteGemini()    { SendCommand("#/mute gemini");     }
function MuteGrok()      { SendCommand("#/mute grok");       }
function MuteCopilot()   { SendCommand("#/mute copilot");    }
function UnmuteClaude()  { SendCommand("#/unmute claude");   }
