    b.SetBackColor("#1e1e1e");
    b.SetTextColor("#cccccc");
    return b;
}

function UpBtn(label) {
    var b = app.CreateButton(label, 0.23, 0.08);
    b.SetTextSize(12);
    b.SetBackColor("#1b361b");
    b.SetTextColor("#66cc66");
