    var payload = { prompt: text, ai: "user" };
    if (targets.length < 4) payload.targets = targets;
    AppendTranscript("You > [" + targets.join(",") + "]", text);
    _promptRef.SetText("");
    try {
        app.HttpRequest("http://" + tunnelIP + "/send", "POST",
            JSON.stringify(payload), "Content-Type:application/json");
