    var rowKB = app.CreateLayout("linear", "Horizontal");
    rowKB.SetSize(0.97, 0.09);
    var kDs  = MkBtn("DeepSearch", 0.30, 0.08); kDs.SetOnTouch(GrokDeepsearch);
    var kIm  = MkBtn("Imagine",    0.23, 0.08); kIm.SetOnTouch(GrokImagine);
    var kPer = MkBtn("Personas",   0.23, 0.08); kPer.SetOnTouch(GrokPersonas);
    rowKB.AddChild(kDs); rowKB.AddChild(kIm); rowKB.AddChild(kPer);
    main.AddChild(rowKB);

    var kConvoBtn = MkBtn("Convos - Grok", 0.50, 0.07);
    kConvoBtn.SetBackColor("#1a1a2e"); kConvoBtn.SetTextColor("#8888ff");
    kConvoBtn.SetOnTouch(ConvosGrok);
    main.AddChild(kConvoBtn);

    // Copilot
    main.AddChild(SectionLabel("COPILOT"));
    var rowPA = app.CreateLayout("linear", "Horizontal");
    rowPA.SetSize(0.97, 0.09);
    var pSide = MkBtn("Sidebar",  0.23, 0.08); pSide.SetOnTouch(CopilotSidebar);
    var pNew  = MkBtn("New Chat", 0.23, 0.08); pNew.SetOnTouch(CopilotNewchat);
    var pLib  = MkBtn("Library",  0.23, 0.08); pLib.SetOnTouch(CopilotLibrary);
    var pUp   = UpBtn("Upload");               pUp.SetOnTouch(CopilotUpload);
    rowPA.AddChild(pSide); rowPA.AddChild(pNew); rowPA.AddChild(pLib); rowPA.AddChild(pUp);
    main.AddChild(rowPA);

    var rowPB = app.CreateLayout("linear", "Horizontal");
    rowPB.SetSize(0.97, 0.09);
    var pSm  = MkBtn("Smart",   0.23, 0.08); pSm.SetOnTouch(CopilotSmart);
    var pSrc = MkBtn("Sources", 0.23, 0.08); pSrc.SetOnTouch(CopilotSources);
    rowPB.AddChild(pSm); rowPB.AddChild(pSrc);
    main.AddChild(rowPB);

    var pConvoBtn = MkBtn("Convos - Copilot", 0.50, 0.07);
    pConvoBtn.SetBackColor("#1a1a2e"); pConvoBtn.SetTextColor("#8888ff");
    pConvoBtn.SetOnTouch(ConvosCopilot);
    main.AddChild(pConvoBtn);

    // Clear transcript
    var btnClr = MkBtn("Clear Transcript", 0.50, 0.07);
    btnClr.SetBackColor("#222222"); btnClr.SetTextColor("#888888");
    btnClr.SetOnTouch(ClearTranscript);
    main.AddChild(btnClr);

    root.AddChild(main);

    // Convo picker overlay — hidden until needed
    _pickerLayout = app.CreateLayout("linear", "VCenter,FillXY");
    _pickerLayout.SetBackColor("#000000");
    _pickerLayout.SetPadding(0.02, 0.02, 0.02, 0.02);
    _pickerLayout.SetVisibility("Gone");

    var pickerTitle = app.CreateText("Select conversation", 1.0, 0.06, "center");
    pickerTitle.SetTextSize(15);
    pickerTitle.SetTextColor("#ffffff");
    _pickerLayout.AddChild(pickerTitle);

    _pickerList = app.CreateList("", 1.0, 0.70);
    _pickerList.SetBackColor("#1a1a1a");
    _pickerList.SetTextColor1("#ffffff");
    _pickerList.SetOnTouch(OnPickerTouch);
    _pickerLayout.AddChild(_pickerList);

    var btnCancel = MkBtn("Cancel", 0.40, 0.08);
    btnCancel.SetBackColor("#3a1a1a"); btnCancel.SetTextColor("#ff8888");
    btnCancel.SetOnTouch(HidePicker);
    _pickerLayout.AddChild(btnCancel);

    app.AddLayout(root);
    app.AddLayout(_pickerLayout);
}

// ── UI helpers ────────────────────────────────────────────────────────────────
function SectionLabel(text) {
    var lbl = app.CreateText(text, 0.97, 0.05, "left");
    lbl.SetTextSize(11);
    lbl.SetTextColor("#446644");
    lbl.SetPadding(0, 0.005, 0, 0);
    return lbl;
}

function MkBtn(label, w, h) {
    var b = app.CreateButton(label, w, h);
    b.SetTextSize(12);
    b.SetBackColor("#1e1e1e");
    b.SetTextColor("#cccccc");
    return b;
}

function UpBtn(label) {
    var b = app.CreateButton(label, 0.23, 0.08);
    b.SetTextSize(12);
    b.SetBackColor("#1b361b");
    b.SetTextColor("#66cc66");
    return b;
}

function SetTargetColor(btn, active) {
    if (active) { btn.SetBackColor("#1a3a1a"); btn.SetTextColor("#88ff88"); }
    else        { btn.SetBackColor("#2a2a2a"); btn.SetTextColor("#555555"); }
}

// ── Target toggles ────────────────────────────────────────────────────────────
function ToggleClaude()  { aiTargets.claude  = !aiTargets.claude;  SetTargetColor(_btnClaude,  aiTargets.claude);  }
function ToggleGemini()  { aiTargets.gemini  = !aiTargets.gemini;  SetTargetColor(_btnGemini,  aiTargets.gemini);  }
function ToggleGrok()    { aiTargets.grok    = !aiTargets.grok;    SetTargetColor(_btnGrok,    aiTargets.grok);    }
function ToggleCopilot() { aiTargets.copilot = !aiTargets.copilot; SetTargetColor(_btnCopilot, aiTargets.copilot); }

// ── Send ──────────────────────────────────────────────────────────────────────
function GetTargets() {
    var t = [];
    for (var i = 0; i < AI_KEYS.length; i++) {
        if (aiTargets[AI_KEYS[i]]) t.push(AI_KEYS[i]);
    }
    return t;
}

function OnSend() {
    var text = _promptRef.GetText().trim();
    if (!text) return;
    if (text.indexOf("#/") === 0) { SendCommand(text); _promptRef.SetText(""); return; }
    var targets = GetTargets();
    var payload = { prompt: text, ai: "user" };
    if (targets.length < 4) payload.targets = targets;
    AppendTranscript("You > [" + targets.join(",") + "]", text);
    _promptRef.SetText("");
    try {
        app.HttpRequest("http://" + tunnelIP + "/send", "POST",
            JSON.stringify(payload), "Content-Type:application/json");
        SetStatus("Sent - " + Stamp());
    } catch(e) { SetStatus("Send error: " + e); }
}

// ── Commands ──────────────────────────────────────────────────────────────────
function SendCommand(cmd) {
    AppendTranscript("CMD", cmd);
    try {
        app.HttpRequest("http://" + tunnelIP + "/command", "POST",
            JSON.stringify({ command: cmd }), "Content-Type:application/json");
        SetStatus(cmd + " - " + Stamp());
    } catch(e) { SetStatus("Cmd error: " + e); }
}

function CmdKill()       { SendCommand("#/kill");           }
function CmdResume()     { SendCommand("#/resume");         }
function CmdStatus()     { SendCommand("#/status");         }
function CmdClear()      { SendCommand("#/clear");          }
function MuteClaude()    { SendCommand("#/mute claude");    }
function MuteGemini()    { SendCommand("#/mute gemini");    }
