// ── Actions ───────────────────────────────────────────────────────────────────
function PostAction(ai, action) {
    try {
        app.HttpRequest("http://" + tunnelIP + "/action", "POST",
            JSON.stringify({ ai:ai, action:action }), "Content-Type:application/json");
        AppendTranscript("Action > " + AI_LABELS[ai], action);
