// ── Convo picker (no ShowListDialog — uses CreateList overlay) ────────────────
function FetchConvos(ai) {
    _convoAI = ai;
    SetStatus("Fetching convos for " + AI_LABELS[ai] + "...");
    try {
        var resp = app.HttpRequest(
            "http://" + tunnelIP + "/conversations?ai=" + ai,
            "GET", "", "");
        if (!resp || resp.length === 0) {
            app.Alert("No conversations returned for " + AI_LABELS[ai]);
            return;
        }
        var data   = JSON.parse(resp);
        var convos = data.conversations || [];
        if (convos.length === 0) {
            app.Alert("No conversations found for " + AI_LABELS[ai]);
            return;
        }
        _convoTitles = [];
        var listStr  = "";
        for (var i = 0; i < convos.length; i++) {
            _convoTitles.push(convos[i].title);
            listStr += (i > 0 ? "," : "") + convos[i].title;
        }
        _pickerList.SetList(listStr, ",");
        _pickerLayout.SetVisibility("Show");
    } catch(e) { SetStatus("Convos error: " + e); }
}

function OnPickerTouch(title) {
    HidePicker();
    if (!title) return;
    var ai = _convoAI;
    try {
        app.HttpRequest("http://" + tunnelIP + "/switch", "POST",
            JSON.stringify({ ai:ai, title:title }), "Content-Type:application/json");
        AppendTranscript("Switch > " + AI_LABELS[ai], title);
        SetStatus("Switched " + AI_LABELS[ai] + " > " + title);
    } catch(e) { SetStatus("Switch error: " + e); }
}

function HidePicker() {
    _pickerLayout.SetVisibility("Gone");
}

function ConvosClaude()  { FetchConvos("claude");  }
function ConvosGemini()  { FetchConvos("gemini");  }
function ConvosGrok()    { FetchConvos("grok");    }
function ConvosCopilot() { FetchConvos("copilot"); }

// ── Poll ──────────────────────────────────────────────────────────────────────
function StartPolling() {
    if (pollTimer) clearInterval(pollTimer);
    pollTimer = setInterval(PollTick, 2000);
}

function PollTick() {
    try {
        var resp = app.HttpRequest("http://" + tunnelIP + "/poll", "GET", "", "");
        if (resp && resp.length > 0) {
            AppendTranscript("<", resp);
            SetStatus("Response - " + Stamp());
        }
    } catch(e) { SetStatus("Poll error - " + Stamp()); }
}

// ── Helpers ───────────────────────────────────────────────────────────────────
function AppendTranscript(label, msg) {
    if (!_transcriptRef) return;
    var prev = _transcriptRef.GetText();
    _transcriptRef.SetText(prev + "\n[" + label + "] " + msg);
    try { _transcriptRef.ScrollTo(99999); } catch(e) {}
}

function ClearTranscript() { if (_transcriptRef) _transcriptRef.SetText(""); }
function SetStatus(msg)    { if (_statusRef) _statusRef.SetText(msg); }

function Stamp() {
    var d = new Date();
    return d.getHours() + ":" +
           ("0" + d.getMinutes()).slice(-2) + ":" +
           ("0" + d.getSeconds()).slice(-2);
}
```

The key change is that `ShowListDialog` is completely gone. The Convos buttons now show a full-screen `CreateList` overlay that you built yourself — tap an item, `OnPickerTouch` fires, tap Cancel, `HidePicker` fires. No `dlg.js` involved at all. 🌹
